//! PRD-mcphost-session-journal-v2
//! contract: walks src/
//! AC6 (P0) — Given the two new fields, When the drift tests run, Then
//! `CallRow::FIELDS`, the `fields` projection, the `host.calls.export` CSV
//! header and the contract files regenerated by `mcphost contract dump`
//! (`api_contract`) list the same fields in the same order, and a source scan
//! finds one `INSERT INTO calls` that names `args_sha256`.

use mcphost::api_contract::dump_contract;
use mcphost::calllog::{CallRow, render_csv};
use mcphost::kinds::KindRegistry;
use serde_json::Value;
use std::path::Path;

fn strings(v: &Value) -> Vec<String> {
    v.as_array().expect("array").iter().map(|s| s.as_str().expect("string").to_string()).collect()
}

fn tool<'a>(contract: &'a Value, name: &str) -> &'a Value {
    contract["tools"]
        .as_array()
        .expect("tools")
        .iter()
        .find(|t| t["name"] == name)
        .unwrap_or_else(|| panic!("{name} is in the contract"))
}

#[test]
fn jrnl_ac06_one_field_list_in_the_row_struct_projection_csv_and_contract() {
    let fields: Vec<String> = CallRow::FIELDS.iter().map(|f| f.to_string()).collect();
    assert_eq!(&fields[fields.len() - 2..], ["args_sha256", "session_id"], "the two new fields end the list");

    // The `fields` projection of the paged verb.
    let spec = mcphost::paged::paged_spec("host.calls.list").expect("host.calls.list pages");
    assert_eq!(spec.fields, CallRow::FIELDS, "paged projection");

    // The export CSV header.
    let csv = render_csv(&[]);
    let header: Vec<String> = csv.lines().next().expect("header").split(',').map(str::to_string).collect();
    assert_eq!(header, fields, "CSV header");

    // The contract the binary builds now and the file `mcphost contract dump` committed.
    let live = dump_contract(&KindRegistry::with_builtin());
    let committed: Value = serde_json::from_slice(
        &std::fs::read(Path::new(env!("CARGO_MANIFEST_DIR")).join("contracts/host-tools.v1.json")).expect("read contract"),
    )
    .expect("parse contract");
    for (label, contract) in [("live contract", &live), ("committed contract", &committed)] {
        let list = tool(contract, "host.calls.list");
        assert_eq!(strings(&list["fields_enum"]), fields, "{label}: fields_enum");
        assert_eq!(strings(&list["input_schema"]["properties"]["fields"]["items"]["enum"]), fields, "{label}: fields items");
        for verb in ["host.calls.list", "host.calls.export"] {
            assert!(
                !tool(contract, verb)["input_schema"]["properties"]["session"].is_null(),
                "{label}: {verb} takes `session`"
            );
        }
    }
}

/// The write-path scan: of every `INSERT INTO calls` in `src/`, exactly one
/// (`record_call_traced`'s) names `args_sha256`, and it names `session_id`
/// beside it.
#[test]
fn jrnl_ac06_one_insert_into_calls_names_args_sha256() {
    fn walk(dir: &Path, out: &mut Vec<std::path::PathBuf>) {
        for entry in std::fs::read_dir(dir).expect("read_dir") {
            let path = entry.expect("entry").path();
            if path.is_dir() {
                walk(&path, out);
            } else if path.extension().is_some_and(|e| e == "rs") {
                out.push(path);
            }
        }
    }
    let mut files = Vec::new();
    walk(&Path::new(env!("CARGO_MANIFEST_DIR")).join("src"), &mut files);
    let mut naming = Vec::new();
    for file in files {
        let text = std::fs::read_to_string(&file).expect("read source");
        for (at, _) in text.match_indices("INSERT INTO calls") {
            let line_start = text[..at].rfind('\n').map_or(0, |i| i + 1);
            if text[line_start..at].trim_start().starts_with("//") {
                continue;
            }
            let statement = &text[at..];
            let upto = statement.find("VALUES").expect("INSERT INTO calls without VALUES");
            if statement[..upto].contains("args_sha256") {
                assert!(statement[..upto].contains("session_id"), "{}: names args_sha256 without session_id", file.display());
                naming.push(file.display().to_string());
            }
        }
    }
    assert_eq!(naming.len(), 1, "exactly one INSERT INTO calls names args_sha256: {naming:?}");
}
